<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Faculty');check_csrf();$f=db()->prepare('SELECT id FROM faculty WHERE user_id=?');$f->execute([actor_id()]);$fid=(int)$f->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){db()->prepare('INSERT INTO projects(title,description,technology,guide_faculty_id,start_date,end_date,repository_url,status) VALUES(?,?,?,?,?,?,?,\'Active\')')->execute([$_POST['title'],$_POST['description'],$_POST['technology'],$fid,$_POST['start_date'],$_POST['end_date'],$_POST['repository_url']]);$_SESSION['flash']=['success','Project created'];redirect('projects.php');}$q=db()->prepare('SELECT * FROM projects WHERE guide_faculty_id=? ORDER BY id DESC');$q->execute([$fid]);page_top('Project Studio');flash();?><div class='card p-4 mb-4'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-6'><input name='title' class='form-control' placeholder='Project title' required></div><div class='col-md-6'><input name='technology' class='form-control' placeholder='Technology stack' required></div><div class='col-12'><textarea name='description' class='form-control' placeholder='Project description'></textarea></div><div class='col-md-3'><input name='start_date' type='date' class='form-control'></div><div class='col-md-3'><input name='end_date' type='date' class='form-control'></div><div class='col-md-6'><input name='repository_url' class='form-control' placeholder='Repository URL'></div><button class='btn btn-primary col-md-2'>Create Project</button></form></div><div class='card p-3 table-responsive'><table class='table'><tr><th>Title</th><th>Technology</th><th>Dates</th><th>Status</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['technology'])?></td><td><?=e($r['start_date'])?> → <?=e($r['end_date'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php page_bottom();
